    // These fixed source paths use only absolute moves, lines, cubics and closes.
    private static func path(_ svg: String) -> Path {
        let expression = try! NSRegularExpression(pattern: #"[MLCZ]|-?(?:\d*\.?\d+)"#)
        let source = svg as NSString
        let tokens = expression.matches(in: svg, range: NSRange(location: 0, length: source.length)).map { source.substring(with: $0.range) }
        var result = Path(), index = 0, command = ""
        func number(_ offset: Int) -> Double { Double(tokens[index + offset])! }
        while index < tokens.count {
            if tokens[index].rangeOfCharacter(from: .letters) != nil {
                command = tokens[index]; index += 1
                if command == "Z" { result.closeSubpath(); continue }
            }
            switch command {
            case "M":
                result.move(to: CGPoint(x: number(0), y: number(1))); index += 2; command = "L"
            case "L":
                result.addLine(to: CGPoint(x: number(0), y: number(1))); index += 2
            case "C":
                result.addCurve(to: CGPoint(x: number(4), y: number(5)), control1: CGPoint(x: number(0), y: number(1)), control2: CGPoint(x: number(2), y: number(3))); index += 6
            default: return result
            }
        }
        return result
    }
    fileprivate static func circle(_ center: CGPoint, _ radius: Double) -> Path {
        Path(ellipseIn: CGRect(x: center.x - radius, y: center.y - radius, width: radius * 2, height: radius * 2))
    }
}


