    static func path(_ name: String) -> Path {
        if let cached = cache.object(forKey: name as NSString) { return cached.path }
        guard let source = outlines[name] else { return Path() }
        let ns = source as NSString
        let values = tokens.matches(in: source, range: NSRange(location: 0, length: ns.length))
            .map { ns.substring(with: $0.range) }
        var path = Path()
        var current = CGPoint.zero
        var start = CGPoint.zero
        var command = ""
        var index = 0
        func number(_ offset: Int) -> Double { Double(values[index + offset]) ?? 0 }
        while index < values.count {
            if values[index].first?.isLetter == true {
                command = values[index]
                index += 1
                if command == "Z" { path.closeSubpath(); current = start; continue }
            }
            switch command {
            case "M", "L":
                guard index + 1 < values.count else { return path }
                current = CGPoint(x: number(0), y: number(1))
                if command == "M" { path.move(to: current); start = current; command = "L" }
                else { path.addLine(to: current) }
                index += 2
            case "H":
                current.x = number(0); path.addLine(to: current); index += 1
            case "V":
                current.y = number(0); path.addLine(to: current); index += 1
            case "Q":
                guard index + 3 < values.count else { return path }
                let control = CGPoint(x: number(0), y: number(1))
                current = CGPoint(x: number(2), y: number(3))
                path.addQuadCurve(to: current, control: control); index += 4
            default: return path
            }
        }
        cache.setObject(UnlockingCheckoutStepsIconPath(path), forKey: name as NSString)
        return path
    }
}

struct UnlockingCheckoutStepsFeatherIcon: View {
    let name: String
    let size: Double
    let color: Color

    var body: some View {
        let path = UnlockingCheckoutStepsIconArt.path(name)
        Canvas { context, _ in
            let scale = size / UnlockingCheckoutStepsIconArt.units
            context.translateBy(x: 0, y: size / 2 + UnlockingCheckoutStepsIconArt.center * scale)
            context.scaleBy(x: scale, y: -scale)
            context.fill(path, with: .color(color))
        }
        .frame(width: size, height: size)
        .accessibilityHidden(true)
    }
}


struct UnlockingCheckoutStepsRouteMap: View {
    let width: Double
    let drawn: Double
    private typealias A = UnlockingCheckoutStepsArt
    var body: some View {
        Canvas { context, _ in
            let scale = width / A.mapWidth
            context.scaleBy(x: scale, y: scale)
            context.fill(Path(CGRect(x: 0, y: 0, width: A.mapWidth, height: A.mapWidth * A.mapRatio)), with: .color(A.mapFill))
            context.stroke(A.blocks, with: .color(A.blocksInk), lineWidth: 1)
            context.stroke(A.avenues, with: .color(A.streetsInk), lineWidth: 7)
            context.stroke(A.streets, with: .color(A.streetsInk), lineWidth: 3.5)
            if drawn > 0 { context.stroke(A.route.trimmedPath(from: 0, to: min(1, drawn)), with: .color(A.teal), style: StrokeStyle(lineWidth: 2.6, lineCap: .round)) }
            context.fill(A.circle(A.routeStart, 5), with: .color(A.teal))
            var arrived = context
            arrived.opacity = min(1, max(0, drawn * 5 - 4))
            arrived.fill(A.circle(A.routeEnd, 5), with: .color(A.teal))
            arrived.fill(A.circle(A.routeEnd, 2), with: .color(.white))
        }.frame(width: width, height: width * A.mapRatio).clipped().accessibilityHidden(true)
    }
}

struct UnlockingCheckoutStepsSuccessArt: View {
    let size: Double
    let checked: Double
    private typealias A = UnlockingCheckoutStepsArt
    var body: some View {
        Canvas { context, _ in
            let scale = size / A.art
            context.scaleBy(x: scale, y: scale)
            var card = context
            card.translateBy(x: 90, y: 58); card.rotate(by: .radians(-0.12)); card.translateBy(x: -90, y: -58)
            let cardPath = Path(roundedRect: CGRect(x: 36, y: 22, width: 108, height: 72), cornerRadius: 12)
            card.fill(cardPath, with: .color(A.cardFill))
            card.stroke(cardPath, with: .color(A.outline), lineWidth: 3)
            card.stroke(Path(roundedRect: CGRect(x: 52, y: 40, width: 28, height: 18), cornerRadius: 5), with: .color(A.outline), lineWidth: 2.4)
            card.stroke(A.cardChip, with: .color(A.outline), style: StrokeStyle(lineWidth: 2, lineCap: .round))
            card.stroke(A.cardWaves, with: .color(A.outline), style: StrokeStyle(lineWidth: 2.4, lineCap: .round))

            let face = Path(CGRect(x: 46, y: 108, width: 104, height: 84))
            context.fill(face, with: .color(A.boxFill))
            context.fill(A.boxTop, with: .color(A.topFill))
            context.fill(A.boxSide, with: .color(A.sideFill))
            context.fill(A.boxTape, with: .color(A.tapeFill))
            let edge = StrokeStyle(lineWidth: 3, lineJoin: .round)
            context.stroke(face, with: .color(A.outline), style: edge)
            context.stroke(A.boxTop, with: .color(A.outline), style: edge)
            context.stroke(A.boxSide, with: .color(A.outline), style: edge)
            context.stroke(A.boxLabel, with: .color(A.outline), style: StrokeStyle(lineWidth: 2.6, lineCap: .round))
            let badge = A.circle(A.badge, A.badgeRadius)
            context.fill(badge, with: .color(A.badgeFill))
            context.stroke(badge, with: .color(A.outline), lineWidth: 3.4)
            if checked > 0 { context.stroke(A.badgeCheck.trimmedPath(from: 0, to: min(1, checked)), with: .color(.white), style: StrokeStyle(lineWidth: 5, lineCap: .round, lineJoin: .round)) }
            context.stroke(A.sparks, with: .color(A.outline), style: StrokeStyle(lineWidth: 3, lineCap: .round))
        }.frame(width: size, height: size).clipped().accessibilityHidden(true)
    }
}
